sys_script_client.script:
// MSSCUSTODY - 4148 - Hide/Show fields based on Outcome for GCS
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var ownBusiness = g_scratchpad.ownB;
    if (ownBusiness == 'GC HK'){
		return;
	}

    if ((ownBusiness == 'DCC UK') || (ownBusiness == 'GC UK')) {
        if (isLoading || newValue === '') {
            var tradeTaskType = g_scratchpad.blkTskRelated;
            var taskState = g_form.getValue('state').toString();
            if ((tradeTaskType == 'Maker') && ((taskState == '1') || (taskState == '2'))) {
                setOnLoadForm(false);
            }
            if ((tradeTaskType == 'Checker') || (tradeTaskType == 'Maker') || (tradeTaskType.indexOf('GHSS') > -1)) {
                showFieldsForChecker(ownBusiness);
            }
            return;
        } else {
            g_form.setMandatory('suspend', false); //Fix for 7046
            g_form.setDisplay('suspend', false);
            g_form.setMandatory('cancellation_reference', false);
            g_form.setDisplay('cancellation_reference', false);
            g_form.setMandatory('fxr_td', false);
            g_form.setDisplay('fxr_td', false); //Fix for 7046
            g_form.setMandatory('settlement_type', false);
            g_form.setDisplay('settlement_type', false); //Fix for 7046
            g_form.setMandatory('value_date', false);
            g_form.setDisplay('value_date', false); //Fix for 7046
            g_form.setDisplay('settlement_date', false); //Fix for 7046

            if (newValue == "Confirm Trade") {
                confirmTrade();
            } else if (newValue == "Process Trade Cancellation") {
                processTradeCancellation(ownBusiness, g_scratchpad.rCodeDCCUK, g_scratchpad.rCodeGCCUK);
            } else if ((newValue == "Settle Trade") || (newValue == "Confirm and Settle Trade")) {   //MSSCUSTODY-7298
                settleTrade();
            } else if ((newValue == "Put 'Trade on Hold'") || (newValue == "Put Trade On-Hold")) {
                putTradeOnHold();
            } else if ((newValue == "Perform(ed) a trade repair/amendment in GCS") || (newValue == "Manually approve the trade in GCS")) { // added as fix for defect 5455
                automatedOutcomes();
                // } else if (newValue == "CONF to STTL") { // added as part of 7240
                //     settleTrade();
            }
        }
    } else {
        g_form.setDisplay('value_date', false);
        g_form.setDisplay('fxr_td', false);
    }
}

function setOnLoadForm(out_1) {

    g_form.setMandatory('settlement_date', out_1);
    g_form.setMandatory('value_date', out_1);
    g_form.setMandatory('fxr_td', out_1);
    g_form.setMandatory('reason_code', out_1);
    g_form.setMandatory('settlement_type', out_1);
    g_form.setMandatory('cancellation_reference', out_1);
    g_form.setMandatory('bk_to_bk_info', out_1);
    g_form.setMandatory('suspend', out_1);


    g_form.setDisplay('settlement_date', out_1);
    g_form.setDisplay('value_date', out_1);
    g_form.setDisplay('fxr_td', out_1);
    g_form.setDisplay('reason_code', out_1);
    g_form.setDisplay('settlement_type', out_1);
    g_form.setDisplay('cancellation_reference', out_1);
    g_form.setDisplay('bk_to_bk_info', out_1);
    g_form.setDisplay('fx_cx', out_1); //MSSCUSTODY-7421
    g_form.setDisplay('gdi', out_1); //MSSCUSTODY-7421

    g_form.clearValue('value_date');
    g_form.clearValue('settlement_date');
    g_form.clearValue('fxr_td');
    g_form.clearValue('reason_code');
    g_form.clearValue('reason_description');
    g_form.clearValue('settlement_type');
    g_form.clearValue('cancellation_reference');
    g_form.clearValue('cancel_by');
    g_form.clearValue('collect_cancel_charge');
    g_form.clearValue('bk_to_bk_info');
    g_form.clearValue('fx_cx'); //MSSCUSTODY-7421
    g_form.clearValue('gdi'); //MSSCUSTODY-7421
}

function showFieldsForChecker(ownBusiness) {
    // Function for displaying fields for checker task
    g_form.setDisplay('collect_cancel_charge', false);
    g_form.setDisplay('fxr_td', false);
    g_form.setDisplay('value_date', false);
    g_form.setDisplay('settlement_date', false);
    g_form.setDisplay('settlement_type', false);
    g_form.setDisplay('reason_code', false);
    g_form.setDisplay('reason_description', false);
    g_form.setDisplay('cancellation_reference', false);
    g_form.setDisplay('bk_to_bk_info', false);
    g_form.setDisplay('advice', false);
    g_form.setDisplay('cancel_by', false); // i added
    g_form.setMandatory('cancel_by', false);
    g_form.setDisplay('fx_cx', false); //MSSCUSTODY-7421
    g_form.setDisplay('gdi', false); //MSSCUSTODY-7421

    var selectedOutcome = g_form.getValue('outcome');
    // MSSCUSTODY - 4699
    var settleTrade = ["value_date", "settlement_date", "settlement_type", "advice"];
    var confirmTrade = ["value_date", "advice"];
    var processTradeCancellation = ["reason_code", "reason_description", "cancellation_reference", "cancel_by", "advice", "fxr_td", "collect_cancel_charge"];
    var putTradeOnHold = ["advice", "suspend", "reason_code", "reason_description"];
    //var cfrmToSttlTrade = ["value_date", "settlement_date", "settlement_type", "advice"];

    if (selectedOutcome == 'Confirm Trade') {
        for (var i = 0; i < confirmTrade.length; i++) {
            g_form.setDisplay(confirmTrade[i], true);
            g_form.setMandatory('value_date', true);
        }
    } else if (selectedOutcome == 'Settle Trade' || newValue == "CONF to STTL") {
        for (i = 0; i < settleTrade.length; i++) {
            g_form.setDisplay(settleTrade[i], true);
        }
        g_form.setMandatory('value_date', true);
        g_form.setMandatory('settlement_type', true);
        g_form.setValue('settlement_type', 'B');
        g_form.setReadOnly('settlement_type', 'true');
        g_form.setDisplay('bk_to_bk_info', true);
        g_form.setReadOnly('advice', true);
        g_form.setMandatory('suspend', false);
        g_form.setLabelOf('settlement_date', 'Actual settlement date'); // fix for MSSCUSTODY-6643
        g_form.setDisplay('settlement_date', true); // fix for MSSCUSTODY-6643
    } else if (selectedOutcome == 'Process Trade Cancellation') {
        for (i = 0; i < processTradeCancellation.length; i++) {
            g_form.setDisplay(processTradeCancellation[i], true);
        }
        g_form.setMandatory('reason_code', true);
        g_form.setMandatory('cancel_by', true);
        g_form.setMandatory('cancellation_reference', true);
        g_form.setMandatory('fxr_td', true);
        g_form.setReadOnly('advice', true);
        if (ownBusiness == 'DCC UK') {
            g_form.setValue('reason_code', g_scratchpad.rCodeDCCUK); // Set reason code as 'CCANI' for DCC UK trades
        } else if (ownBusiness == 'GC UK') {
            g_form.setValue('reason_code', g_scratchpad.rCodeGCCUK); // Set reason code as 'CCANI' for GC UK trades
        }
        g_form.setReadOnly('reason_code', true);
    } else if (selectedOutcome == 'Put Trade On-Hold' || selectedOutcome == "Put 'Trade on Hold'" || selectedOutcome == "No remediation of corresponding Switch trade possible - put each 'Trade on Hold'") {
        for (i = 0; i < putTradeOnHold.length; i++) {
            g_form.setDisplay(putTradeOnHold[i], true);
            g_form.setMandatory('reason_code', true);
            g_form.setLabelOf('reason_code', 'Further Identification Code');
            g_form.setDisplay('suspend', true);
            g_form.setMandatory('suspend', true); //5387 fix
            g_form.setReadOnly('suspend', true);
            g_form.setValue('suspend', 'Y')
            g_form.setReadOnly('advice', true);
        }
    } else if (selectedOutcome == "Perform(ed) a trade repair/amendment in GCS" || selectedOutcome == "Manually approve the trade in GCS") {
        g_form.setDisplay('cancellation_reference', false);
        g_form.setDisplay('fxr_td', false);
        g_form.setDisplay('value_date', false);
        g_form.setDisplay('settlement_date', false);
        g_form.setDisplay('settlement_type', false);
    }
    // } else if (selectedOutcome == 'CONF to STTL') {
    //     for (i = 0; i < cfrmToSttlTrade.length; i++) {
    //         g_form.setDisplay(settleTrade[i], true);
    //     }
    //     g_form.setMandatory('value_date', true);
    //     g_form.setMandatory('settlement_type', true);
    //     g_form.setValue('settlement_type', 'B');
    //     g_form.setReadOnly('settlement_type', 'true');
    //     g_form.setDisplay('bk_to_bk_info', true);
    //     g_form.setReadOnly('advice', true);
    //     g_form.setMandatory('suspend', false);
    // 	g_form.setLabelOf('settlement_date', 'Actual settlement date'); // fix for MSSCUSTODY-6643
    // 	g_form.setDisplay('settlement_date', true); // fix for MSSCUSTODY-6643
    // }
}

function settleTrade() {
    // Enable fields for Settle Trade Outcome
    g_form.setMandatory('value_date', true);
    g_form.setDisplay('value_date', true);
    g_form.setMandatory('settlement_date', false);
    g_form.setDisplay('settlement_date', true);
    g_form.setLabelOf('settlement_date', 'Actual settlement date'); // fix for MSSCUSTODY-6643
    g_form.setDisplay('settlement_type', true);
    g_form.setMandatory('settlement_type', true);
    g_form.setValue('settlement_type', 'B');
    g_form.setReadOnly('settlement_type', true);
    g_form.setMandatory('bk_to_bk_info', false);
    g_form.setDisplay('bk_to_bk_info', false);
    g_form.setDisplay('advice', true);
    g_form.setReadOnly('advice', true);

    // Disabling fields for Settle Trade
    g_form.setMandatory('suspend', false);
    g_form.setValue('suspend', '');
    g_form.setMandatory('reason_code', false);
    g_form.setDisplay('reason_code', false);
    g_form.setValue('reason_code', '');
    g_form.setValue('reason_description', '');
    g_form.setLabelOf('reason_code', 'Reason Code');
    g_form.setMandatory('fxr_td', false);
    g_form.setDisplay('fxr_td', false);
    g_form.setMandatory('cancellation_reference', false);
    g_form.setDisplay('cancellation_reference', false);

}

function confirmTrade() {

    // Enable fields for Confirm Trade Outcome
    g_form.setMandatory('value_date', true);
    g_form.setDisplay('value_date', true);
    g_form.setDisplay('advice', true);

    // Disabling fields for confirm trade
    g_form.setMandatory('settlement_type', false);
    g_form.setDisplay('settlement_type', false);
    g_form.setValue('settlement_type', '');
    g_form.setMandatory('settlement_date', false);
    g_form.setDisplay('settlement_date', false);
    g_form.setMandatory('reason_code', false);
    g_form.setDisplay('reason_code', false);
    g_form.setValue('reason_code', '');
    g_form.setValue('reason_description', '');
    g_form.setLabelOf('reason_code', 'Reason Code');
    g_form.setMandatory('fxr_td', false);
    g_form.setDisplay('fxr_td', false);
    g_form.setMandatory('cancellation_reference', false);
    g_form.setDisplay('cancellation_reference', false);
    g_form.setMandatory('bk_to_bk_info', false);
    g_form.setDisplay('bk_to_bk_info', false);
}

function processTradeCancellation(market, reasonCodeDCC, reasonCodeGC) {

    // Displaying fields for cancel Trade
    g_form.setMandatory('reason_code', true);
    g_form.setDisplay('reason_code', true);
    g_form.setDisplay('fxr_td', true);
    if (market == 'DCC UK') {
        g_form.setValue('reason_code', reasonCodeDCC); // Set reason code as 'CCANI' for DCC UK trades
    } else if (market == 'GC UK') {
        g_form.setValue('reason_code', reasonCodeGC); // Set reason code as 'CCANI' for GC UK trades
    }
    g_form.setReadOnly('reason_code', true);
    g_form.setReadOnly('advice', true);
    g_form.setMandatory('cancellation_reference', true);
    g_form.setDisplay('cancellation_reference', true);
    g_form.setMandatory('fxr_td', true); // Make FXRTD mandatory

    // Disabling fields for Cancel Trade
    g_form.setMandatory('settlement_type', false);
    g_form.setDisplay('settlement_type', false);
    g_form.setValue('settlement_type', '');
    g_form.setMandatory('settlement_date', false);
    g_form.setDisplay('settlement_date', false);
    g_form.setMandatory('value_date', false);
    g_form.setDisplay('value_date', false);
    g_form.setLabelOf('reason_code', 'Reason Code');
    g_form.setMandatory('bk_to_bk_info', false);
    g_form.setDisplay('bk_to_bk_info', false);

}

function putTradeOnHold() {
    g_form.setDisplay('suspend', true);
    g_form.setMandatory('suspend', true);
    // Enable fields for Put trade On Hold Outcome
    g_form.setValue('suspend', 'Y');
    g_form.setReadOnly('suspend', true);
    g_form.setReadOnly('reason_code', false);
    g_form.setMandatory('reason_code', true);
    g_form.setLabelOf('reason_code', 'Further Identification Code');
    g_form.setDisplay('reason_code', true);

    // // Disabling fields for Put Trade on Hold
    g_form.setMandatory('settlement_type', false);
    g_form.setDisplay('settlement_type', false);
    g_form.setValue('settlement_type', '');
    g_form.setMandatory('value_date', false);
    g_form.setDisplay('value_date', false);
    g_form.setMandatory('settlement_date', false);
    g_form.setDisplay('settlement_date', false);
    g_form.setValue('reason_code', '');
    g_form.setValue('reason_description', '');
    g_form.setMandatory('fxr_td', false);
    g_form.setDisplay('fxr_td', false);
    g_form.setMandatory('cancellation_reference', false);
    g_form.setDisplay('cancellation_reference', false);
    g_form.setDisplay('bk_to_bk_info', false);
    g_form.setDisplay('advice', true); //MSSCUSTODY-4883
    g_form.setReadOnly('advice', true); //MSSCUSTODY-4883

}

function automatedOutcomes() {
    g_form.setMandatory('value_date', false);
    g_form.setMandatory('cancellation_reference', false);
    g_form.setMandatory('fxr_td', false);
    g_form.setMandatory('settlement_type', false);
    g_form.setDisplay('cancellation_reference', false);
    g_form.setDisplay('value_date', false);
    g_form.setDisplay('fxr_td', false);
    g_form.setDisplay('settlement_date', false);
    g_form.setDisplay('settlement_type', false);
}
